<?php
declare(strict_types=1);
namespace App\Domain\Quiz;
final class QuizResult { private function __construct(private QuizResultId $id, private QuizSessionId $quizId, private string $studentName, private int $score, private int $total, private float $percentage, private int $duration, private string $answersJson, private \DateTimeImmutable $createdAt) {} public static function create(QuizResultId $id, QuizSessionId $quizId, string $studentName, int $score, int $total, int $duration, string $answersJson): self { $p=$total>0?($score/$total)*100:0.0; return new self($id,$quizId,$studentName,$score,$total,$p,$duration,$answersJson,new \DateTimeImmutable('now', new \DateTimeZone('UTC'))); } public static function reconstitute(QuizResultId $id, QuizSessionId $quizId, string $studentName, int $score, int $total, float $percentage, int $duration, string $answersJson, \DateTimeImmutable $createdAt): self { return new self($id,$quizId,$studentName,$score,$total,$percentage,$duration,$answersJson,$createdAt); } public function id(): QuizResultId { return $this->id; } public function quizId(): QuizSessionId { return $this->quizId; } public function studentName(): string { return $this->studentName; } public function score(): int { return $this->score; } public function total(): int { return $this->total; } public function percentage(): float { return $this->percentage; } public function duration(): int { return $this->duration; } public function answersJson(): string { return $this->answersJson; } public function createdAt(): \DateTimeImmutable { return $this->createdAt; }}
